pragma solidity >=0.8.0;
contract GasProbe {
    uint8 public marker;
    uint64 public stamp;
    uint256 public entryGas;
    uint256 public exitGas;
    event GasRecorded(uint256 entryG, uint256 exitG);
    function getGas() public view returns (uint256) {
        return gasleft();
    }
    function recordEntry() public {
        marker = 1;
        stamp = uint64(block.number);
        entryGas = gasleft();
        uint256 s = 0;
        unchecked {
            for (uint256 i = 0; i < 20; i++) {
                s += i * 7;
            }
        }
        exitGas = gasleft();
        emit GasRecorded(entryGas, exitGas);
    }
}
